<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>PoseArt - Typography Audit</title>
    <style>
        :root {
            --bg-color: #FDF6E3;
            --text-primary: #1A2E35;
            --text-secondary: #4A5D62;
            --accent-gold: #D4AF37;

            /* Font Families */
            --font-serif: "Playfair Display", "Times New Roman", serif;
            --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            font-family: var(--font-sans);
            color: var(--text-primary);
            display: flex;
            justify-content: center;
            min-height: 100vh;
            /* Simulating mobile view for audit */
            max-width: 480px; 
            margin: 0 auto;
            position: relative;
            box-shadow: 0 0 20px rgba(0,0,0,0.05);
        }

        .container {
            width: 100%;
            padding: 20px;
            padding-bottom: 80px; /* Space for nav */
        }

        /* --- Header Section --- */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 24px;
            font-family: var(--font-sans);
        }

        .time {
            font-size: 16px;
            font-weight: 600; /* Semi-bold */
            letter-spacing: 0.5px;
        }

        .logo {
            font-family: var(--font-sans); /* Sans-serif as per image visual */
            text-transform: uppercase;
            letter-spacing: 2px;
            font-weight: 700;
            font-size: 18px;
        }

        /* --- Hero / Greeting --- */
        .greeting {
            margin-bottom: 24px;
        }

        .greeting h1 {
            font-family: var(--font-serif);
            font-size: 32px;
            font-weight: 400; /* Regular or slightly elegant */
            line-height: 1.2;
            color: var(--text-primary);
            margin-bottom: 4px;
        }

        .greeting p {
            font-family: var(--font-sans);
            font-size: 15px;
            line-height: 1.5;
            color: var(--text-secondary);
            font-weight: 400;
        }

        /* --- Featured Card --- */
        .featured-card {
            background: linear-gradient(135deg, #2F5C55 0%, #2A7C8E 100%);
            border-radius: 20px;
            padding: 20px;
            display: flex;
            align-items: center;
            gap: 16px;
            margin-bottom: 32px;
            box-shadow: 0 10px 20px rgba(47, 92, 85, 0.2);
            position: relative;
            overflow: hidden;
        }

        /* Decorative circle in bg */
        .featured-card::after {
            content: '';
            position: absolute;
            right: -20px;
            top: -20px;
            width: 120px;
            height: 120px;
            border-radius: 50%;
            border: 1px solid rgba(255,255,255,0.1);
        }

        .card-img-placeholder {
            width: 70px;
            height: 90px;
            background-color: white;
            border-radius: 8px;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: #999;
        }

        .card-content {
            flex-grow: 1;
            z-index: 1;
        }

        .card-label {
            font-family: var(--font-sans);
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            color: rgba(255,255,255,0.9);
            font-weight: 700;
            margin-bottom: 6px;
        }

        .card-title {
            font-family: var(--font-serif);
            font-size: 22px;
            color: white;
            font-weight: 500;
            margin-bottom: 12px;
            line-height: 1.2;
        }

        .btn-start {
            background-color: #D4AF37;
            color: #1A2E35;
            border: none;
            padding: 10px 20px;
            border-radius: 20px;
            font-family: var(--font-sans);
            font-size: 14px;
            font-weight: 700;
            cursor: pointer;
            display: inline-block;
        }

        /* --- Categories Grid --- */
        .section-title {
            font-family: var(--font-sans);
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 16px;
            color: var(--text-primary);
        }

        .grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;
        }

        .category-card {
            aspect-ratio: 1.3 / 1; /* Rectangular cards */
            border-radius: 16px;
            padding: 16px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            position: relative;
            overflow: hidden;
            transition: transform 0.2s;
        }

        .category-card:hover {
            transform: translateY(-2px);
        }

        /* Card Colors (Approximated from screenshot) */
        .c-teal-dark { background-color: #1B4D4A; }
        .c-teal { background-color: #1F6B68; }
        .c-blue { background-color: #2E5FA3; }
        .c-blue-light { background-color: #367CA8; }
        .c-gold { background-color: #B59D50; }
        .c-gold-light { background-color: #CDB85D; }
        .c-purple { background-color: #5E4578; }
        .c-purple-deep { background-color: #4A3864; }
        .c-orange { background-color: #C86F4E; }
        .c-green { background-color: #4A9B82; }

        .cat-text {
            z-index: 2;
        }

        .cat-title {
            font-family: var(--font-sans);
            font-size: 15px;
            font-weight: 500;
            color: white;
            margin-bottom: 4px;
            line-height: 1.3;
            /* Handling potential wrapping gracefully */
            word-wrap: break-word;
        }

        .cat-count {
            font-family: var(--font-sans);
            font-size: 13px;
            font-weight: 400;
            color: rgba(255,255,255,0.8);
        }

        .cat-icon {
            align-self: flex-end;
            opacity: 0.3;
            font-size: 40px;
            color: white;
            position: absolute;
            bottom: 10px;
            right: 10px;
        }

        /* --- Navigation Bar --- */
        .nav-bar {
            position: fixed;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 100%;
            max-width: 480px;
            background-color: #1A2E35;
            height: 70px;
            display: flex;
            justify-content: space-around;
            align-items: center;
            border-top-left-radius: 20px;
            border-top-right-radius: 20px;
            z-index: 100;
            padding-bottom: env(safe-area-inset-bottom);
        }

        .nav-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            color: #8AA0A8;
            text-decoration: none;
            font-size: 11px;
            font-family: var(--font-sans);
            font-weight: 500;
            gap: 4px;
            transition: color 0.2s;
        }

        .nav-item.active {
            color: #D4AF37;
        }

        .nav-item span.icon {
            font-size: 20px;
            line-height: 1;
        }

        /* Center FAB Button */
        .fab-container {
            position: absolute;
            top: -25px;
            background-color: #D4AF37;
            width: 56px;
            height: 56px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 10px rgba(0,0,0,0.3);
            color: #1A2E35;
            font-size: 28px;
            font-weight: 300;
        }

        /* Floating Action Button (Right side) */
        .fab-right {
            position: fixed;
            bottom: 100px;
            right: calc(50% - 220px); /* Offset based on container */
            width: 48px;
            height: 48px;
            background-color: #D4AF37;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            color: #1A2E35;
            box-shadow: 0 4px 12px rgba(212, 175, 55, 0.4);
            z-index: 90;
        }

        @media (min-width: 481px) {
             .fab-right {
                right: calc(50% + 200px);
             }
        }

        /* Typography Specific Fixes/Audits */
        .truncate-test {
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        /* Orphan control example */
        p.prevent-orphan {
            display: inline-block;
        }

    </style>
</head>
<body>

